{
  "hypotheses": [
    {
      "text": "Data‑artifact: IBM’s XBRL filings tag revenue only with the legacy 'Revenues' concept; the newer 'RevenueFromContractWithCustomerExcludingAssessedTax' concept is absent because IBM has not updated its taxonomy tagging.",
      "how_to_test": "SELECT COUNT(*) AS fact_cnt FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact WHERE cik = '51143' AND concept = 'RevenueFromContractWithCustomerExcludingAssessedTax';"
    },
    {
      "text": "Data‑artifact: IBM’s rows for that concept exist but are filtered out because they have a NULL period_frame (indicating duplicate/follow‑on filings) and the view excludes NULL period_frame values.",
      "how_to_test": "SHOW DQ ALL INVALID TABLE lightning.metastore.explainwhy.explainwhy_usl.revenue_fact; -- look for rows with cik='51143' and concept='RevenueFromContractWithCustomerExcludingAssessedTax' that violate PK/FK (e.g., duplicate period_frame NULL). Then run: SELECT COUNT(*) FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact WHERE cik = '51143' AND concept = 'RevenueFromContractWithCustomerExcludingAssessedTax' AND period_frame IS NULL;"
    },
    {
      "text": "Real‑world: IBM has not adopted ASC 606 (Revenue from Contracts with Customers) reporting, so it does not populate the RevenueFromContractWithCustomerExcludingAssessedTax concept in its XBRL submissions.",
      "how_to_test": "SELECT cik, COUNT(*) AS cnt FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact WHERE concept = 'RevenueFromContractWithCustomerExcludingAssessedTax' AND cik IN ('320193','51143','1318605') GROUP BY cik; -- Expect IBM (51143) count = 0 while Apple and Tesla have >0."
    },
    {
      "text": "Real‑world: IBM reports revenue using other US‑GAAP elements (e.g., RevenueFromLicensingArrangements, ServiceRevenue) rather than the generic contract‑revenue concept, so the specific concept is intentionally omitted.",
      "how_to_test": "SELECT DISTINCT concept FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact WHERE cik = '51143' AND concept LIKE '%Revenue%'; -- Verify IBM has revenue‑related concepts other than the two target ones."
    }
  ]
}
